/**
 * The header both apps print on a person's PAYE report PDF (rulebook §25 / §26 Reports, 1.33.0, owner 6 Nov: "reports
 * must look like the invoice / timesheet report … proper header (logo, company, person, payrun) … generated by / at").
 *
 * Only text: when and by whom a saved report was generated, in the organisation zone ("6 Nov 2026, 14:05 by Sam
 * Smith"). Each report's own rows function (`overtimeReportRows`, `payeClaimReportRows`) returns these fields so no
 * app formats a report date itself.
 */

import { formatStampInZone } from '../orgTime/zoneTime'
import { zoneOrLondon } from './dayKeys'

export type ReportGeneratedInput = {
  /** The saved copy's `generatedAt` (server time), or null while it is not back yet. */
  generatedAtMs?: number | null
  /** Used while `generatedAtMs` is null (the report was just saved). */
  nowMs?: number | null
  /** Organisation zone; London when missing. */
  timeZone?: string | null
  /** The saved copy's `generatedBy` (users id). */
  generatedBy?: string | null
  /** The report's person (`userId`, `userName`): a report is generated by its own person, so their name is the default. */
  userId?: string | null
  userName?: string | null
  /** The generator's display name when the app knows it (a roster lookup of `generatedBy`). Wins over the default. */
  generatedByName?: string | null
}

export type ReportGeneratedText = {
  /** "6 Nov 2026, 14:05" in the organisation zone; "" when neither time is known. */
  generatedAt: string
  /** The generator's name; "" when unknown. */
  generatedBy: string
  /** "6 Nov 2026, 14:05 by Sam Smith" (or either part alone). */
  generated: string
}

function text(value: unknown): string {
  return value == null ? '' : String(value).trim()
}

/**
 * When and by whom a saved report was generated. The time is `generatedAtMs`, else `nowMs`; the name is
 * `generatedByName`, else the report's own person when `generatedBy` is their id (or not stored).
 */
export function reportGeneratedText(input: ReportGeneratedInput): ReportGeneratedText {
  const ms = Number.isFinite(Number(input.generatedAtMs)) && input.generatedAtMs != null ? Number(input.generatedAtMs) : input.nowMs != null && Number.isFinite(Number(input.nowMs)) ? Number(input.nowMs) : null
  const generatedAt = ms == null ? '' : formatStampInZone(new Date(ms), zoneOrLondon(input.timeZone))
  const by = text(input.generatedBy)
  const generatedBy = text(input.generatedByName) || (!by || by.toLowerCase() === text(input.userId).toLowerCase() ? text(input.userName) : '')
  const generated = generatedAt && generatedBy ? `${generatedAt} by ${generatedBy}` : generatedAt || generatedBy
  return { generatedAt, generatedBy, generated }
}
